import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';

const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox', '--disable-dev-shm-usage'] });
const page = await browser.newPage({ viewport: { width: 1200, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });

await page.route('**/src/main.js*', async (route) => {
  const response = await route.fetch();
  let body = await response.text();
  body = body.replace(
    'function clamp(value, min, max) {',
    'window.test = { THREE, state, player, camera };\nfunction clamp(value, min, max) {'
  );
  await route.fulfill({ response, body });
});

await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
await page.locator('#startBtn').click();
await page.waitForTimeout(300);

const reset = async () => page.evaluate(() => {
  test.state.cameraYaw = 0;
  test.state.cameraPitch = 0;
  test.state.joystick.x = 0;
  test.state.joystick.y = 0;
  test.player.position.set(0, 0, 0);
  test.player.rotation.y = 0;
});
const snapshot = async () => page.evaluate(() => ({
  pos: test.player.position.toArray(),
  rotY: test.player.rotation.y,
  cameraYaw: test.state.cameraYaw,
  view: test.camera.getWorldDirection(new test.THREE.Vector3()).toArray(),
  screenRight: new test.THREE.Vector3().setFromMatrixColumn(test.camera.matrixWorld, 0).toArray()
}));
const dot = (a, b) => a.reduce((sum, value, i) => sum + value * b[i], 0);

async function keyboardRun(key) {
  await reset();
  await page.waitForTimeout(100);
  const before = await snapshot();
  await page.keyboard.down(key);
  await page.waitForTimeout(450);
  await page.keyboard.up(key);
  const after = await snapshot();
  const delta = after.pos.map((v, i) => v - before.pos[i]);
  const len = Math.hypot(...delta);
  const facing = [Math.sin(after.rotY), 0, Math.cos(after.rotY)];
  return {
    delta,
    screenRightDot: dot(delta, before.screenRight),
    forwardDot: dot(delta, before.view),
    facingDot: len ? dot(delta.map((v) => v / len), facing) : 0
  };
}

const d = await keyboardRun('d');
const a = await keyboardRun('a');
const w = await keyboardRun('w');
const s = await keyboardRun('s');

await reset();
await page.waitForTimeout(100);
const beforeJoystick = await snapshot();
const rect = await page.locator('#joystickZone').boundingBox();
const cx = rect.x + rect.width / 2;
const cy = rect.y + rect.height / 2;
await page.mouse.move(cx, cy);
await page.mouse.down();
await page.mouse.move(cx + rect.width * 0.24, cy, { steps: 6 });
await page.waitForTimeout(450);
await page.mouse.up();
const afterJoystick = await snapshot();
const joystickDelta = afterJoystick.pos.map((v, i) => v - beforeJoystick.pos[i]);
const joystickLen = Math.hypot(...joystickDelta);
const joystickFacing = [Math.sin(afterJoystick.rotY), 0, Math.cos(afterJoystick.rotY)];
const joystickRight = {
  delta: joystickDelta,
  screenRightDot: dot(joystickDelta, beforeJoystick.screenRight),
  facingDot: joystickLen ? dot(joystickDelta.map((v) => v / joystickLen), joystickFacing) : 0
};

await reset();
await page.waitForTimeout(100);
const beforeDrag = await snapshot();
await page.mouse.move(900, 300);
await page.mouse.down();
await page.mouse.move(1000, 300, { steps: 8 });
await page.mouse.up();
await page.waitForTimeout(150);
const afterDrag = await snapshot();
const cameraDrag = {
  cameraYaw: afterDrag.cameraYaw,
  view: afterDrag.view,
  turnedTowardOldScreenRight: dot(afterDrag.view, beforeDrag.screenRight)
};

console.log(JSON.stringify({ d, a, w, s, joystickRight, cameraDrag, errors }, null, 2));
await browser.close();
