import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';
const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox', '--disable-dev-shm-usage'] });
const page = await browser.newPage({ viewport: { width: 1200, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
page.on('console', (m) => { if (m.type() === 'error') errors.push(`console: ${m.text()}`); });
await page.route('**/src/main.js*', async (route) => {
  const response = await route.fetch();
  let body = await response.text();
  body = body.replace(
    'function clamp(value, min, max) {',
    'window.test = { THREE, state, player, camera, treeData, lowObstacles, leftArm, rightArm, leftLeg, rightLeg, getGroundHeight };\nfunction clamp(value, min, max) {'
  );
  await route.fulfill({ response, body });
});
await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
await page.locator('#startBtn').click();
await page.waitForTimeout(400);

const results = {};
const reset = async (x = 0, z = -5) => page.evaluate(({ x, z }) => {
  test.state.cameraYaw = 0;
  test.state.cameraPitch = 0;
  test.state.cameraDistance = 5.7;
  test.state.joystick.x = 0;
  test.state.joystick.y = 0;
  test.state.velocityY = 0;
  test.state.grounded = true;
  test.state.jumpHeld = false;
  test.player.position.set(x, test.getGroundHeight(x, z), z);
  test.player.rotation.y = 0;
}, { x, z });
const snap = async () => page.evaluate(() => ({
  pos: test.player.position.toArray(),
  y: test.player.position.y,
  ground: test.getGroundHeight(test.player.position.x, test.player.position.z),
  rotY: test.player.rotation.y,
  view: test.camera.getWorldDirection(new test.THREE.Vector3()).toArray(),
  screenRight: new test.THREE.Vector3().setFromMatrixColumn(test.camera.matrixWorld, 0).toArray(),
  yaw: test.state.cameraYaw,
  grounded: test.state.grounded,
  vy: test.state.velocityY,
  armL: [test.leftArm.rotation.x, test.leftArm.rotation.z],
  armR: [test.rightArm.rotation.x, test.rightArm.rotation.z],
  legL: test.leftLeg.rotation.x,
  legR: test.rightLeg.rotation.x,
  cameraDistance: test.camera.position.distanceTo(test.player.position)
}));
const dot = (a, b) => a.reduce((sum, value, i) => sum + value * b[i], 0);

async function keyMove(key) {
  await reset();
  await page.waitForTimeout(80);
  const before = await snap();
  await page.keyboard.down(key);
  await page.waitForTimeout(280);
  await page.keyboard.up(key);
  const after = await snap();
  const delta = after.pos.map((v, i) => v - before.pos[i]);
  return { delta, rightDot: dot(delta, before.screenRight), forwardDot: dot(delta, before.view), rotY: after.rotY };
}
results.keys = { d: await keyMove('d'), a: await keyMove('a'), w: await keyMove('w'), s: await keyMove('s') };

await reset();
await page.waitForTimeout(80);
const joystickBefore = await snap();
const rect = await page.locator('#joystickZone').boundingBox();
const cx = rect.x + rect.width / 2;
const cy = rect.y + rect.height / 2;
await page.mouse.move(cx, cy);
await page.mouse.down();
await page.mouse.move(cx + rect.width * 0.25, cy, { steps: 4 });
await page.waitForTimeout(300);
const joystickDuring = await snap();
await page.mouse.up();
const joystickDelta = joystickDuring.pos.map((v, i) => v - joystickBefore.pos[i]);
results.joystickRight = { delta: joystickDelta, rightDot: dot(joystickDelta, joystickBefore.screenRight) };

await reset();
await page.waitForTimeout(80);
await page.keyboard.down('Shift');
const jumpSamples = [];
for (let i = 0; i < 20; i += 1) {
  await page.waitForTimeout(110);
  const s = await snap();
  jumpSamples.push({ t: (i + 1) * 110, y: +s.y.toFixed(2), vy: +s.vy.toFixed(2), grounded: s.grounded, armL: s.armL.map((v) => +v.toFixed(2)), armR: s.armR.map((v) => +v.toFixed(2)) });
}
await page.keyboard.up('Shift');
await page.waitForTimeout(700);
const landed = await snap();
results.jump = {
  maxY: Math.max(...jumpSamples.map((s) => s.y)),
  takeoffs: jumpSamples.filter((s, i) => i > 0 && jumpSamples[i - 1].grounded && !s.grounded).length + (jumpSamples[0] && !jumpSamples[0].grounded ? 1 : 0),
  risingArms: jumpSamples.find((s) => !s.grounded && s.vy > 1)?.armL,
  fallingArms: jumpSamples.find((s) => !s.grounded && s.vy < -1)?.armR,
  landed: { grounded: landed.grounded, y: +landed.y.toFixed(2), ground: +landed.ground.toFixed(2), armL: landed.armL.map((v) => +v.toFixed(2)) }
};

await reset();
const walkSamples = [];
await page.keyboard.down('d');
for (let i = 0; i < 8; i += 1) {
  await page.waitForTimeout(90);
  const s = await snap();
  walkSamples.push({ armL: +s.armL[0].toFixed(2), armR: +s.armR[0].toFixed(2), legL: +s.legL.toFixed(2), legR: +s.legR.toFixed(2) });
}
await page.keyboard.up('d');
results.walk = { samples: walkSamples, opposedPairs: walkSamples.some((s) => s.legL * s.legR < -0.05 && s.armL * s.armR < -0.05) };

const jumpRock = await page.evaluate(() => {
  const obstacle = test.lowObstacles.find((o) => test.treeData.every((t) => Math.hypot(t.position.x - o.x, t.position.z - o.z) > 2.5));
  if (!obstacle) return null;
  test.state.cameraYaw = 0;
  test.state.velocityY = 0;
  test.state.grounded = true;
  test.player.position.set(obstacle.x - 1.35, test.getGroundHeight(obstacle.x - 1.35, obstacle.z), obstacle.z);
  return { x: obstacle.x, z: obstacle.z, top: obstacle.top };
});
await page.waitForTimeout(60);
await page.keyboard.down('a');
await page.waitForTimeout(350);
const autoJumpState = await snap();
await page.keyboard.up('a');
results.autoJump = { rock: jumpRock, grounded: autoJumpState.grounded, vy: +autoJumpState.vy.toFixed(2), y: +autoJumpState.y.toFixed(2) };
await page.waitForTimeout(900);

await reset();
await page.waitForTimeout(80);
const beforeDrag = await snap();
await page.mouse.move(900, 300);
await page.mouse.down();
await page.mouse.move(1000, 300, { steps: 6 });
await page.mouse.up();
await page.waitForTimeout(120);
const afterDrag = await snap();
results.cameraDrag = { yaw: +afterDrag.yaw.toFixed(2), turnedRight: +dot(afterDrag.view, beforeDrag.screenRight).toFixed(2) };

results.errors = errors;
console.log(JSON.stringify(results, null, 2));
await browser.close();
