node --input-type=module <<'JS'
import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';
const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox', '--disable-dev-shm-usage'] });
const page = await browser.newPage({ viewport: { width: 1200, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
page.on('console', (m) => { if (m.type() === 'error') errors.push(`console: ${m.text()}`); });
await page.route('**/src/main.js*', async (route) => {
  const res = await route.fetch();
  let body = await res.text();
  body = body.replace(
    'function clamp(value, min, max) {',
    'window.test = { THREE, state, player, camera, treeData, campfire, droppedLogs, fireSparks, getGroundHeight, interact, updateHud };\\nfunction clamp(value, min, max) {'
  );
  await route.fulfill({ response: res, body });
});
await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
await page.locator('#startBtn').click();
await page.waitForTimeout(700);

const results = {};

const hud = async () => page.evaluate(() => ({
  wood: document.querySelector('#woodText').textContent,
  night: document.querySelector('#nightText').textContent,
  fuel: document.querySelector('#fuelText').textContent,
  fuelWidth: document.querySelector('#fuelFill').style.width,
  fuelClasses: document.querySelector('#fuelFill').className,
  status: document.querySelector('#statusText').textContent,
  warning: document.querySelector('#fireWarning').classList.contains('visible'),
  dark: document.querySelector('#darkness').classList.contains('out'),
  label: document.querySelector('#interactLabel').textContent,
  stateWood: test.state.wood,
  stateFuel: +test.state.fuel.toFixed(1),
  fireOut: test.state.fireOut,
  fireSparksVisible: test.fireSparks.visible
}));

results.initial = await hud();

// Fuel drain.
await page.waitForTimeout(1600);
results.drained = await hud();

// Low / critical colors.
for (const fuel of [70, 40, 10]) {
  await page.evaluate((value) => { test.state.fuel = value; test.updateHud(); }, fuel);
  results[`fuel${fuel}`] = await hud();
}

// Feed fire from near the campfire with wood.
await page.evaluate(() => {
  test.state.fuel = 10;
  test.state.fireOut = false;
  test.state.wood = 2;
  test.state.interactCooldown = 0;
  test.player.position.set(0, test.getGroundHeight(0, -3.2), -3.2);
});
await page.waitForTimeout(200);
results.beforeFeed = await hud();
await page.keyboard.press('e');
await page.waitForTimeout(250);
results.afterFeed = await hud();

// Fire out state and recovery.
await page.evaluate(() => {
  test.state.fuel = 0;
  test.state.fireOut = false;
  test.updateHud();
});
await page.waitForTimeout(350);
results.fireOut = await hud();
await page.waitForTimeout(4600);
results.fireOutAfterFade = await hud();
await page.evaluate(() => { test.state.wood = 1; test.state.interactCooldown = 0; });
await page.keyboard.press('e');
await page.waitForTimeout(500);
results.afterRefuel = await hud();

// Chop the nearest choppable tree three times.
const chopSetup = await page.evaluate(() => {
  const tree = test.treeData
    .filter((t) => t.userData.choppable)
    .sort((a, b) => Math.hypot(a.position.x, a.position.z) - Math.hypot(b.position.x, b.position.z))[0];
  const dx = tree.position.x;
  const dz = tree.position.z;
  const len = Math.hypot(dx, dz);
  const px = tree.position.x - (dx / len) * 1.35;
  const pz = tree.position.z - (dz / len) * 1.35;
  test.player.position.set(px, test.getGroundHeight(px, pz), pz);
  test.state.interactCooldown = 0;
  test.state.wood = 0;
  test.droppedLogs.length = 0;
  test.updateHud();
  return { tree: [tree.position.x, tree.position.z], player: [px, pz], hits: tree.userData.hits, choppable: tree.userData.choppable };
});
await page.waitForTimeout(250);
results.chopPrompt = await hud();
const hitSamples = [];
for (let i = 0; i < 3; i += 1) {
  await page.keyboard.press('e');
  await page.waitForTimeout(420);
  hitSamples.push(await page.evaluate(() => {
    const tree = test.treeData.find((t) => t.userData.choppable && Math.hypot(t.position.x - test.player.position.x, t.position.z - test.player.position.z) < 3);
    return {
      hits: tree?.userData.hits,
      shake: +(tree?.userData.shake || 0).toFixed(2),
      logs: test.droppedLogs.length,
      wood: test.state.wood,
      logPositions: test.droppedLogs.map((log) => [ +log.mesh.position.x.toFixed(2), +log.mesh.position.y.toFixed(2), +log.mesh.position.z.toFixed(2), log.landed ])
    };
  }));
}
results.hits = hitSamples;
await page.waitForTimeout(900);
results.afterPickup = await hud();

results.errors = errors;
console.log(JSON.stringify(results, null, 2));
await page.screenshot({ path: '/tmp/opencode/survival-desktop.jpg', type: 'jpeg', quality: 74 });
await browser.close();
