import puppeteer from 'puppeteer-core';
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const browser = await puppeteer.launch({ executablePath: '/usr/bin/chromium', headless: 'new', args: ['--no-sandbox','--disable-dev-shm-usage','--enable-unsafe-swiftshader'] });
const page = await browser.newPage();
await page.setViewport({ width: 1100, height: 760 });
page.on('pageerror', e => console.log('PAGEERROR', String(e)));
page.on('console', m => { if (m.type()==='error') console.log('CONSOLE', m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'domcontentloaded' });
await page.waitForFunction(() => window.__nightsDebug);
await page.click('#startBtn');
await wait(300);
await page.evaluate(() => {
  const d = window.__nightsDebug;
  d.state.cycleTime = 180.02;
  d.state.fuel = 100;
  d.state.fireOut = false;
  d.state.invuln = 999;
  d.player.position.set(20, d.getGroundHeight(20, 20), 20);
  d.player.rotation.y = 0;
  d.state.cameraYaw = 0;
  for (let i = 0; i < d.enemies.length; i++) {
    const e = d.enemies[i];
    if (i < 2) {
      e.visible = true;
      e.userData.dead = false;
      e.userData.fading = false;
      e.userData.health = 3;
      e.userData.speed = 0;
      e.position.set(20 + (i === 0 ? -1.3 : 1.3), d.getGroundHeight(20, 26), 26);
      e.userData.attackCooldown = 99;
    } else e.visible = false;
  }
});
await wait(900);
await page.screenshot({ path: '/tmp/opencode/browser-test/monsters.png' });
await browser.close();

