await page.goto('http://localhost:3002/', { waitUntil: 'domcontentloaded' });
await page.waitForFunction(() => window.__nightsDebug, { timeout: 20000 });
await wait(400);
await page.tap('#startBtn');
await wait(500);
const probe = await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.state.backpack.berry = 0;
  d.equipTool('backpack');
  const item = d.spawnGroundItem('berry', d.player.position.x + 0.9, d.player.position.z, { velocityY: 0, pickupDelay: 0 });
  item.landed = true;
  item.mesh.position.y = item.groundY + item.restY;
  d.pickUpItem(item);
  const samples = [];
  for (let i = 0; i < 8; i += 1) {
    await new Promise((r) => setTimeout(r, 100));
    samples.push({ t: i * 100, popping: item.popping, inArr: d.groundItems.includes(item), inScene: item.mesh.parent !== null });
  }
  return { samples, berries: d.state.backpack.berry, groundCount: d.groundItems.length };
});
console.log(JSON.stringify(probe, null, 1));
await browser.close();

