import puppeteer from 'puppeteer-core';
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const browser = await puppeteer.launch({ executablePath: '/usr/bin/chromium', headless: 'new', args: ['--no-sandbox','--disable-dev-shm-usage','--enable-unsafe-swiftshader'] });
const page = await browser.newPage();
await page.setViewport({ width: 600, height: 400, isMobile: true, hasTouch: true, deviceScaleFactor: 3 });
await page.goto('http://localhost:3002/', { waitUntil: 'domcontentloaded' });
await page.waitForFunction(() => window.__nightsDebug, { timeout: 20000 });
await wait(400);
await page.tap('#startBtn');
await wait(500);
await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.state.cameraDistance = 2.8;
  d.state.cameraYaw = 0.5;
  d.equipTool('axe');
  d.player.position.set(0, d.getGroundHeight(0, 0), 0);
  await new Promise((r) => setTimeout(r, 1200));
});
await page.screenshot({ path: '/tmp/opencode/browser-test/zoom-axe.png' });
await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.equipTool('backpack');
  await new Promise((r) => setTimeout(r, 900));
});
await page.screenshot({ path: '/tmp/opencode/browser-test/zoom-backpack.png' });
await browser.close();

