await page.goto('http://localhost:3002/', { waitUntil: 'domcontentloaded' });
await page.waitForFunction(() => window.__nightsDebug, { timeout: 20000 });
await wait(400);
await page.tap('#startBtn');
await wait(4500);
await page.evaluate(() => {
  const d = window.__nightsDebug;
  d.state.backpack.wood = 4;
  d.state.backpack.berry = 2;
  d.updateHud();
  d.equipTool('backpack');
});
await wait(800);
await page.screenshot({ path: '/tmp/opencode/browser-test/normal-backpack.png' });
await page.evaluate(() => window.__nightsDebug.equipTool('axe'));
await wait(800);
await page.screenshot({ path: '/tmp/opencode/browser-test/normal-axe.png' });
// Carried items showcase: 3 berries floating behind player.
await page.evaluate(async () => {
  const d = window.__nightsDebug;
  d.unequipTool();
