:root {
  --bg-1: #040b10;
  --bg-2: #0b1d22;
  --panel: rgba(7, 17, 22, 0.66);
  --panel-border: rgba(255, 178, 74, 0.42);
  --text: #edf4ff;
  --muted: #9fb8c0;
  --gold: #ffba58;
  --danger: #ff5d5d;
  --safe: #8aec9b;
}

* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: radial-gradient(circle at center, var(--bg-2), var(--bg-1) 55%);
  color: var(--text);
  font-family: Arial, Helvetica, sans-serif;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
}

body {
  position: relative;
}

button {
  font-family: inherit;
  color: var(--text);
  cursor: pointer;
  -webkit-touch-callout: none;
}

#game {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  background: #030b10;
}

#darkness {
  position: fixed;
  inset: 0;
  z-index: 13;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(circle at 50% 58%, rgba(0, 0, 0, 0.04), rgba(0, 0, 0, 0.62) 78%);
  transition: opacity 2.2s ease;
}

/* ---------- Top HUD ---------- */

#hud {
  position: fixed;
  top: max(8px, env(safe-area-inset-top));
  left: 0;
  right: 0;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 8px;
  padding-left: max(10px, env(safe-area-inset-left));
  padding-right: max(10px, env(safe-area-inset-right));
  pointer-events: none;
  z-index: 20;
}

.panel {
  min-width: 94px;
  padding: 8px 11px;
  background: var(--panel);
  border: 1px solid var(--panel-border);
  border-radius: 14px;
  box-shadow: 0 0 18px rgba(0, 0, 0, 0.22);
  text-align: center;
}

.panel.center {
  min-width: 178px;
  flex: 1;
  max-width: 300px;
  margin: 0 auto;
}

.label {
  font-size: 9px;
  letter-spacing: 0.13em;
  color: var(--muted);
  text-transform: uppercase;
}

.value {
  margin-top: 4px;
  font-size: clamp(20px, 3vw, 28px);
  font-weight: 700;
}

.mini-value {
  font-size: 15px;
  font-weight: 700;
  color: var(--gold);
  line-height: 1;
  white-space: nowrap;
}

.status {
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  height: 76px;
  font-size: 12px;
  border-color: rgba(255, 160, 90, 0.7);
  background: radial-gradient(circle at 34% 28%, rgba(255, 190, 94, 0.54), rgba(76, 31, 18, 0.7));
  box-shadow: 0 0 24px rgba(255, 157, 57, 0.25), inset 0 1px rgba(255, 255, 255, 0.2);
  opacity: 0;
  transform: scale(0.72);
  pointer-events: none;
}

#attackBtn.visible {
  opacity: 1;
  transform: scale(1);
  pointer-events: auto;
}

/* ---------- Hotbar ---------- */

#hotbar {
  position: fixed;
  left: 50%;
  bottom: max(10px, env(safe-area-inset-bottom));
  z-index: 22;
  display: flex;
  align-items: flex-end;
  gap: 10px;
  padding: 6px;
  transform: translateX(-50%);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 18px;
  background: rgba(4, 10, 14, 0.42);
  box-shadow: 0 6px 22px rgba(0, 0, 0, 0.22);
  pointer-events: auto;
}

.hotbar-slot {
  position: relative;
  width: 54px;
  height: 54px;
  margin: 0;
  padding: 8px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 14px;
  background: linear-gradient(180deg, rgba(32, 47, 54, 0.62), rgba(8, 16, 20, 0.68));
  box-shadow: inset 0 1px rgba(255, 255, 255, 0.1), 0 3px 10px rgba(0, 0, 0, 0.25);
  transition: transform 0.16s cubic-bezier(0.2, 0.8, 0.3, 1.25), border-color 0.16s ease, box-shadow 0.16s ease, opacity 0.16s ease, background 0.16s ease;
  touch-action: none;
  will-change: transform;
}

.hotbar-slot svg {
  display: block;
  width: 100%;
  height: 100%;
  filter: drop-shadow(0 2px 2px rgba(0, 0, 0, 0.5));
}

.hotbar-slot:not(.equipped) {
  opacity: 0.68;
}

.hotbar-slot.equipped {
  border: 2px solid #ffffff;
  background: linear-gradient(180deg, rgba(82, 108, 118, 0.78), rgba(17, 30, 36, 0.82));
  box-shadow: 0 0 18px rgba(255, 255, 255, 0.5), 0 8px 18px rgba(0, 0, 0, 0.4), inset 0 1px rgba(255, 255, 255, 0.28);
  opacity: 1;
  transform: translateY(-8px) scale(1.08);
}

.hotbar-num {
  position: absolute;
  left: 5px;
  bottom: 3px;
  color: rgba(255, 255, 255, 0.62);
  font-size: 8px;
  font-weight: 700;
  line-height: 1;
}

.hotbar-badge {
  position: absolute;
  right: -7px;
  top: -8px;
  min-width: 34px;
  padding: 2px 5px;
  border-radius: 999px;
  background: rgba(255, 188, 92, 0.94);
  color: #1b1005;
  font-size: 8px;
  font-weight: 700;
  line-height: 1.2;
  text-align: center;
  box-shadow: 0 2px 7px rgba(0, 0, 0, 0.42);
  pointer-events: none;
