/* ---------- Inventory ---------- */

.inventory-panel {
  position: fixed;
  left: 50%;
  bottom: max(84px, calc(env(safe-area-inset-bottom) + 84px));
  z-index: 26;
  display: flex;
  flex-direction: column;
  width: min(430px, calc(100vw - 28px));
  max-height: min(60vh, 330px);
  overflow: hidden;
  border: 1px solid rgba(255, 210, 130, 0.42);
  border-radius: 16px;
  background: rgba(6, 14, 18, 0.94);
  box-shadow: 0 14px 42px rgba(0, 0, 0, 0.5);
  transform: translateX(-50%);
  transition: opacity 0.2s ease, transform 0.2s ease;
  pointer-events: auto;
}

.inventory-panel.hidden {
  opacity: 0;
  transform: translate(-50%, 10px) scale(0.97);
  pointer-events: none;
}

.inventory-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
