/* ---------- Audio controls ---------- */

#audioControls {
  position: fixed;
  top: max(8px, env(safe-area-inset-top));
  right: max(10px, env(safe-area-inset-right));
  z-index: 24;
  display: flex;
  gap: 6px;
  pointer-events: auto;
}

.audio-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  margin: 0;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 50%;
  background: rgba(6, 16, 21, 0.76);
  color: #d9e6ea;
  box-shadow: 0 3px 12px rgba(0, 0, 0, 0.32), inset 0 1px rgba(255, 255, 255, 0.1);
  touch-action: none;
}

.audio-btn svg {
  width: 18px;
  height: 18px;
}

.audio-btn:active {
  transform: scale(0.92);
}

.audio-btn.muted {
  color: #ff9a8f;
  border-color: rgba(255, 120, 110, 0.5);
  background: rgba(42, 9, 11, 0.8);
}

.sound-slash {
  display: none;
}

.audio-btn.muted .sound-wave {
  display: none;
}

.audio-btn.muted .sound-slash {
  display: block;
}

.settings-panel {
  position: fixed;
  top: calc(max(8px, env(safe-area-inset-top)) + 44px);
  right: max(10px, env(safe-area-inset-right));
  z-index: 33;
  width: min(232px, calc(100vw - 20px));
  padding: 10px 12px 12px;
  border: 1px solid rgba(255, 210, 130, 0.38);
  border-radius: 14px;
  background: rgba(6, 14, 18, 0.95);
  box-shadow: 0 12px 34px rgba(0, 0, 0, 0.5);
  transition: opacity 0.18s ease, transform 0.18s ease, visibility 0s linear 0s;
  pointer-events: auto;
}

.settings-panel.hidden {
  opacity: 0;
  visibility: hidden;
  transform: translateY(-6px) scale(0.97);
  transition: opacity 0.18s ease, transform 0.18s ease, visibility 0s linear 0.18s;
  pointer-events: none;
}

.settings-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--gold);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
}

.settings-close {
  width: 30px;
  height: 30px;
  margin: 0;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.07);
  color: #e8f0f2;
  font-size: 16px;
  line-height: 1;
}

.volume-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-top: 8px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.volume-row b {
  color: var(--gold);
  font-size: 10px;
  letter-spacing: 0.04em;
}

.volume-slider {
  width: 100%;
  height: 30px;
  margin: 4px 0 0;
  accent-color: #ffba58;
  touch-action: pan-x;
}

.volume-slider::-webkit-slider-runnable-track {
  height: 5px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.16);
}

.volume-slider::-webkit-slider-thumb {
  width: 20px;
  height: 20px;
  margin-top: -7px;
  border: 1px solid rgba(255, 240, 200, 0.9);
  border-radius: 50%;
  background: linear-gradient(180deg, #ffd88e, #d78a2d);
  box-shadow: 0 0 12px rgba(255, 186, 88, 0.45);
  -webkit-appearance: none;
}

.settings-note {
  margin-top: 4px;
  color: rgba(159, 184, 192, 0.72);
  font-size: 9px;
  line-height: 1.35;
}

/* ---------- Upgrade machine panel ---------- */

.upgrade-panel {
  position: fixed;
  left: 50%;
  top: 50%;
  z-index: 34;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: min(600px, calc(100vw - 22px));
