async (page) => {
  const out = {};
  out.fetchSize = await page.evaluate(async () => {
    const t = await (await fetch('/src/style.css?q=' + Date.now(), {cache:'no-store'})).text();
    return { len: t.length, hasVis: t.includes('.inventory-panel.hidden {\\n  opacity: 0;\\n  visibility: hidden') || t.includes('.inventory-panel.hidden { opacity: 0; visibility: hidden') };
  });
  await page.evaluate(async () => {
    const link = document.querySelector('link[rel="stylesheet"]');
    const old = link.href;
    link.remove();
    const n = document.createElement('link');
    n.rel = 'stylesheet';
    n.href = '/src/style.css?q=' + Date.now();
    document.head.appendChild(n);
    await new Promise(r => { n.onload = r; setTimeout(r, 3000); });
    window.__cssLink = n.href;
  });
  await page.waitForTimeout(500);
  out.afterReload = await page.evaluate(() => {
    const rules = [];
    for (const sheet of document.styleSheets) {
      try { for (const r of sheet.cssRules) if (r.selectorText === '.inventory-panel.hidden') rules.push(r.cssText); } catch(e) {}
    }
    return { rules, links: [...document.querySelectorAll('link[rel="stylesheet"]')].map(l=>l.getAttribute('href')), vis: getComputedStyle(document.getElementById('inventoryPanel')).visibility };
  });
  return out;
}

