import { createRequire } from 'node:module'
import { readFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, process.platform === 'darwin' ? 'metal.json' : 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()

const outDir = '/tmp/opencode/browser-test/upgrade2'
mkdirSync(outDir, { recursive: true })
const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 1024, height: 640 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 })
const errors = []
page.on('pageerror', error => errors.push('PAGEERROR: ' + error.message))
page.on('console', message => { if (message.type() === 'error') errors.push('CONSOLE: ' + message.text()) })

const result = {}
try {
  await page.goto('http://localhost:3002', { waitUntil: 'load' })
  await page.waitForFunction(() => !!window.__nightsDebug)
  await page.locator('#startBtn').click()
  await page.waitForTimeout(500)
  result.started = await page.evaluate(() => window.__nightsDebug.state.started)
  result.audio = await page.evaluate(() => ({
    started: window.__nightsDebug.audio.started,
    state: window.__nightsDebug.audio.ctx?.state,
    volume: window.__nightsDebug.audio.volume
  }))
  result.slotsInitially = await page.evaluate(() => ['pickaxeSlot','ironAxeSlot','ironSwordSlot'].map(id => document.getElementById(id).classList.contains('hidden')))
  result.machineParts = await page.evaluate(() => {
    const d = window.__nightsDebug
    return { children: d.machine.children.length, fuel: d.machineState.fuel, rocks: d.ironRocks.length }
  })

  await page.evaluate(() => {
    const d = window.__nightsDebug
    d.state.backpack.wood = 20
    d.state.backpack.iron = 10
    d.updateHud()
    d.openMachinePanel()
  })
  await page.waitForTimeout(300)
  result.panelOpen = await page.locator('#upgradePanel').isVisible()
  result.panelBox = await page.locator('#upgradePanel').boundingBox()
  result.upgradeCards = await page.locator('.upgrade-card').count()
  await page.screenshot({ path: join(outDir, 'machine-panel.png') })

  await page.locator('#machineFeedBtn').click()
  await page.waitForTimeout(250)
  result.fuelAfterFeed = await page.evaluate(() => window.__nightsDebug.machineState.fuel)
  result.woodAfterFeed = await page.evaluate(() => window.__nightsDebug.state.backpack.wood)

  await page.locator('.upgrade-card[data-upgrade="ironAxe"]').click()
  await page.waitForTimeout(200)
  result.working = await page.evaluate(() => window.__nightsDebug.machineState.working)
  result.machineRunning = await page.evaluate(() => window.__nightsDebug.audio.machineRunning)
  await page.screenshot({ path: join(outDir, 'machine-working.png') })

  result.craft = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.machineState.progress = 9.95
    d.machineState.fuel = 100
    d.updateMachine(0.2)
    const item = d.groundItems.find(i => i.type === 'ironAxe')
    return {
      working: d.machineState.working,
      outputSpawned: !!item,
      ding: d.machineState.statusText,
      fuel: d.machineState.fuel
    }
  })

  result.collect = await page.evaluate(() => {
    const d = window.__nightsDebug
    const item = d.groundItems.find(i => i.type === 'ironAxe')
    const picked = d.pickUpItem(item)
    return {
      picked,
      owned: d.state.ownedTools.ironAxe,
      equipped: d.state.equippedTool,
      slotHidden: document.getElementById('ironAxeSlot').classList.contains('hidden'),
      attackVisible: document.getElementById('attackBtn').classList.contains('visible')
    }
  })
  await page.waitForTimeout(300)
  await page.screenshot({ path: join(outDir, 'iron-axe-equipped.png') })

  result.mining = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.closeMachinePanel()
    d.state.ownedTools.pickaxe = true
    d.equipTool('pickaxe')
    const rock = d.ironRocks.find(r => !r.broken)
    d.player.position.x = rock.x - 1.2
    d.player.position.z = rock.z
    d.updateHud()
    const before = d.groundItems.filter(i => i.type === 'iron').length
    d.mineIronRock(rock, 1)
    const afterFirst = { hit: rock.hits, broken: rock.broken, visible: rock.group.visible }
    d.mineIronRock(rock, 1)
    const afterSecond = { hit: rock.hits, broken: rock.broken, visible: rock.group.visible }
    const after = d.groundItems.filter(i => i.type === 'iron').length
    return { before, afterFirst, afterSecond, after, pickaxeEquipped: d.state.equippedTool, slotHidden: document.getElementById('pickaxeSlot').classList.contains('hidden') }
  })

  result.ironPickup = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.equipTool('backpack')
    const item = d.groundItems.find(i => i.type === 'iron' && !i.carried && i.popping <= 0)
    const before = d.state.backpack.iron
    d.pickUpItem(item)
    return { hadItem: !!item, before, after: d.state.backpack.iron, ironHud: document.getElementById('ironText').textContent }
  })

  result.structures = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.state.backpack.wood = 50
    d.state.backpack.iron = 50
    const wallBefore = d.placedWalls.length
    const wallItem = d.spawnGroundItem('ironWall', d.player.position.x + 1, d.player.position.z, { pickupDelay: 0 })
    d.pickUpItem(wallItem)
    const wallAfter = d.placedWalls.length
    const fireBefore = d.state.fireLevel
    const fireItem = d.spawnGroundItem('biggerCampfire', d.player.position.x + 1, d.player.position.z, { pickupDelay: 0 })
    d.pickUpItem(fireItem)
    return { wallBefore, wallAfter, fireBefore, fireAfter: d.state.fireLevel, campfireScale: d.campfire.scale.x }
  })

  await page.locator('#audioToggle').click()
  await page.waitForTimeout(150)
  result.muted = await page.evaluate(() => ({ muted: window.__nightsDebug.audio.muted, cls: document.getElementById('audioToggle').classList.contains('muted') }))
  await page.locator('#audioToggle').click()
  await page.locator('#settingsBtn').click()
  await page.waitForTimeout(200)
  result.settingsOpen = await page.locator('#settingsPanel').isVisible()
  result.settingsBox = await page.locator('#settingsPanel').boundingBox()
  await page.locator('#volumeSlider').fill('35')
  await page.waitForTimeout(150)
  result.volume = await page.evaluate(() => ({ volume: window.__nightsDebug.audio.volume, label: document.getElementById('volumeValue').textContent }))
  await page.screenshot({ path: join(outDir, 'settings.png') })
  await page.locator('#closeSettingsBtn').click()

  await page.setViewportSize({ width: 844, height: 390 })
  await page.waitForTimeout(300)
  await page.evaluate(() => window.__nightsDebug.openMachinePanel())
  await page.waitForTimeout(250)
  result.mobilePanel = {
    visible: await page.locator('#upgradePanel').isVisible(),
    box: await page.locator('#upgradePanel').boundingBox(),
    hotbar: await page.locator('#hotbar').boundingBox(),
    viewport: await page.evaluate(() => ({ w: innerWidth, h: innerHeight }))
  }
  await page.screenshot({ path: join(outDir, 'machine-mobile.png') })

  await page.setViewportSize({ width: 568, height: 320 })
  await page.waitForTimeout(300)
  result.smallPanel = {
    box: await page.locator('#upgradePanel').boundingBox(),
    viewport: await page.evaluate(() => ({ w: innerWidth, h: innerHeight }))
  }
  await page.screenshot({ path: join(outDir, 'machine-small.png') })

  result.errors = errors
} catch (error) {
  result.failure = String(error && error.stack || error)
  result.errors = errors
  try { await page.screenshot({ path: join(outDir, 'failure.png') }) } catch {}
} finally {
  await browser.close()
}
console.log(JSON.stringify(result, null, 2))

