import { createRequire } from 'node:module'
import { readFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, process.platform === 'darwin' ? 'metal.json' : 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()

const outDir = '/tmp/opencode/browser-test/upgrade3'
mkdirSync(outDir, { recursive: true })
const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 844, height: 390 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 })
const errors = []
page.on('pageerror', error => errors.push('PAGEERROR: ' + error.message))
page.on('console', message => { if (message.type() === 'error') errors.push('CONSOLE: ' + message.text()) })
const result = {}
try {
  await page.goto('http://localhost:3002', { waitUntil: 'load' })
  await page.waitForFunction(() => !!window.__nightsDebug)
  await page.locator('#startBtn').click()
  await page.waitForTimeout(600)
  await page.screenshot({ path: join(outDir, 'spawn.png') })

  result.audio = await page.evaluate(() => ({ started: window.__nightsDebug.audio.started, ctx: window.__nightsDebug.audio.ctx?.state }))

  result.missing = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.state.backpack.wood = 2
    d.state.backpack.iron = 0
    d.updateHud()
    d.openMachinePanel()
    d.startUpgrade('ironAxe')
    return { toast: document.getElementById('toast').textContent, working: d.machineState.working }
  })
  await page.waitForTimeout(150)
  await page.screenshot({ path: join(outDir, 'missing-materials.png') })

  result.stall = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.state.backpack.wood = 20
    d.state.backpack.iron = 20
    d.machineState.fuel = 100
    d.startUpgrade('pickaxe')
    d.machineState.fuel = 0.15
    d.machineState.progress = 5
    d.updateMachine(1)
    const stalled = { stalled: d.machineState.stalled, progress: d.machineState.progress, fuel: d.machineState.fuel, hum: d.audio.machineRunning }
    d.addMachineFuel()
    d.machineState.fuel = 10
    d.updateMachine(0.5)
    return { stalled, resumed: { stalled: d.machineState.stalled, progress: d.machineState.progress, fuel: d.machineState.fuel, hum: d.audio.machineRunning } }
  })

  result.craftAndCollect = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.machineState.progress = 9.95
    d.machineState.fuel = 50
    d.updateMachine(0.2)
    const item = d.groundItems.find(i => i.type === 'pickaxe')
    const picked = d.pickUpItem(item)
    return { picked, owned: d.state.ownedTools.pickaxe, equipped: d.state.equippedTool, slot: !document.getElementById('pickaxeSlot').classList.contains('hidden') }
  })

  result.mining = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.closeMachinePanel()
    const rock = d.ironRocks.find(r => !r.broken)
    d.player.position.x = rock.x - 1.1
    d.player.position.z = rock.z
    d.state.equippedTool = 'pickaxe'
    d.updateHud()
    d.updateInteractionTarget?.()
    d.mineIronRock(rock)
    d.mineIronRock(rock)
    const ironItems = d.groundItems.filter(i => i.type === 'iron' && !i.carried)
    return { broken: rock.broken, regrow: rock.regrow, drops: ironItems.length }
  })

  result.ironPickup = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.state.backpack = { wood: 0, sapling: 0, berry: 0, iron: 0 }
    d.equipTool('backpack')
    const items = d.groundItems.filter(i => i.type === 'iron' && !i.carried && i.popping <= 0)
    const picked = d.pickUpItem(items[0])
    return { picked, iron: d.state.backpack.iron, hud: document.getElementById('ironText').textContent, badge: document.getElementById('backpackBadge').textContent }
  })

  result.inventoryIron = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.setInventoryOpen(true)
    return { open: !!document.getElementById('inventoryPanel').offsetParent, text: document.getElementById('inventoryList').innerText, ironRow: !!document.querySelector('.inv-icon.iron') }
  })
  await page.waitForTimeout(200)
  await page.screenshot({ path: join(outDir, 'inventory-iron.png') })

  result.regrow = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.setInventoryOpen(false)
    const rock = d.ironRocks.find(r => r.broken)
    rock.regrow = 0.01
    d.updateIronRocks(0.02)
    d.updateIronRocks(0.6)
    return { broken: rock.broken, visible: rock.group.visible, scale: rock.group.scale.x }
  })

  result.allTools = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.state.ownedTools.ironAxe = true
    d.state.ownedTools.ironSword = true
    d.updateHud()
    const visible = [...document.querySelectorAll('.hotbar-slot')].filter(e => !e.classList.contains('hidden')).map(e => e.id)
    return { visible, count: visible.length }
  })
  await page.waitForTimeout(200)
  await page.screenshot({ path: join(outDir, 'hotbar-all.png') })

  result.machinePanel = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.state.backpack.wood = 30
    d.state.backpack.iron = 20
    d.machineState.fuel = 100
    d.openMachinePanel()
    d.updateHud()
    return true
  })
  await page.waitForTimeout(250)
  result.panelBox = await page.locator('#upgradePanel').boundingBox()
  await page.screenshot({ path: join(outDir, 'panel-mobile.png') })

  result.mute = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.toggleAudioMute()
    const muted = { muted: d.audio.muted, gain: d.audio.master.gain.value }
    d.toggleAudioMute()
    return { muted, unmuted: { muted: d.audio.muted, gain: d.audio.master.gain.value } }
  })

  result.errors = errors
} catch (error) {
  result.failure = String(error && error.stack || error)
  result.errors = errors
  try { await page.screenshot({ path: join(outDir, 'failure.png') }) } catch {}
} finally {
  await browser.close()
}
console.log(JSON.stringify(result, null, 2))

