import { createRequire } from 'node:module'
import { readFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, process.platform === 'darwin' ? 'metal.json' : 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()

const outDir = '/tmp/opencode/browser-test/upgrade4'
mkdirSync(outDir, { recursive: true })
const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 844, height: 390 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 })
const errors = []
page.on('pageerror', error => errors.push('PAGEERROR: ' + error.message))
page.on('console', message => { if (message.type() === 'error') errors.push('CONSOLE: ' + message.text()) })
const result = {}
try {
  await page.goto('http://localhost:3002', { waitUntil: 'load' })
  await page.waitForFunction(() => !!window.__nightsDebug)
  await page.locator('#startBtn').click()
  await page.waitForTimeout(700)

  result.initial = await page.evaluate(() => {
    const d = window.__nightsDebug
    return {
      toast: document.getElementById('toast').textContent,
      starterIron: d.groundItems.filter(i => i.type === 'iron' && !i.carried).length,
      audio: { started: d.audio.started, state: d.audio.ctx?.state },
      hud: {
        iron: document.getElementById('ironText').textContent,
        counters: document.querySelectorAll('.counter-row .counter').length
      }
    }
  })

  // Bootstrap pickup: collect one loose iron and 4 wood, then craft the pickaxe.
  result.bootstrap = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.equipTool('backpack')
    const iron = d.groundItems.find(i => i.type === 'iron' && !i.carried && i.popping <= 0)
    d.pickUpItem(iron)
    d.state.backpack.wood = 4
    d.updateHud()
    d.openMachinePanel()
    const before = { wood: d.state.backpack.wood, iron: d.state.backpack.iron }
    document.querySelector('.upgrade-card[data-upgrade="pickaxe"]').dispatchEvent(new PointerEvent('pointerdown', { bubbles: true }))
    return {
      before,
      working: d.machineState.working,
      after: { wood: d.state.backpack.wood, iron: d.state.backpack.iron },
      status: document.getElementById('machineStatus').textContent,
      pickaxeCardCost: document.querySelector('.upgrade-card[data-upgrade="pickaxe"] .upgrade-cost').textContent
    }
  })
  await page.waitForTimeout(250)
  await page.screenshot({ path: join(outDir, 'machine-working-mobile.png') })

  result.owned = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.machineState.progress = 9.95
    d.machineState.fuel = 100
    d.updateMachine(0.2)
    d.updateMachinePanel()
    const item = d.groundItems.find(i => i.type === 'pickaxe')
    const picked = d.pickUpItem(item)
    d.updateMachinePanel()
    const costText = document.querySelector('.upgrade-card[data-upgrade="pickaxe"] .upgrade-cost').textContent
    const before = { wood: d.state.backpack.wood, iron: d.state.backpack.iron }
    document.querySelector('.upgrade-card[data-upgrade="pickaxe"]').dispatchEvent(new PointerEvent('pointerdown', { bubbles: true }))
    return {
      picked,
      equipped: d.state.equippedTool,
      costText,
      owned: document.querySelector('.upgrade-card[data-upgrade="pickaxe"]').classList.contains('owned'),
      duplicateBlocked: d.machineState.working === null,
      resourcesUnchanged: d.state.backpack.wood === before.wood && d.state.backpack.iron === before.iron,
      toast: document.getElementById('toast').textContent
    }
  })

  // Costs may come from hands as well as the backpack.
  result.fromHands = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.closeMachinePanel()
    d.state.backpack.wood = 0
    d.state.backpack.iron = 0
    d.state.ownedTools.ironAxe = false
    d.state.equippedTool = null
    const wood = d.spawnGroundItem('wood', d.player.position.x + 0.4, d.player.position.z, { pickupDelay: 0 })
    const iron = d.spawnGroundItem('iron', d.player.position.x + 0.7, d.player.position.z, { pickupDelay: 0 })
    d.pickUpItem(wood)
    d.pickUpItem(iron)
    d.carriedItems.push(
      ...Array.from({ length: 5 }, () => d.spawnGroundItem('wood', d.player.position.x + 1, d.player.position.z, { pickupDelay: 0 })).map(item => {
        item.carried = true
        item.landed = true
        d.carriedItems.push(item)
        return item
      })
    )
    d.state.machineOpen = true
