import { createRequire } from 'node:module'
import { readFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, process.platform === 'darwin' ? 'metal.json' : 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const outDir = '/tmp/opencode/browser-test/upgrade5'
mkdirSync(outDir, { recursive: true })
const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 568, height: 320 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 })
const errors = []
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message))
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()) })
const result = {}
try {
  await page.goto('http://localhost:3002', { waitUntil: 'load' })
  await page.waitForFunction(() => !!window.__nightsDebug)
  await page.locator('#startBtn').click()
  await page.waitForTimeout(500)
  result.interact = await page.evaluate(async () => {
    const d = window.__nightsDebug
    d.player.position.x = 4.8
    d.player.position.z = -1
    d.state.cameraYaw = 1.7
    await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)))
    const nearby = d.state.machineInReach
    d.interact()
    return { nearby, open: d.state.machineOpen, panel: !document.getElementById('upgradePanel').classList.contains('hidden') }
  })
  await page.evaluate(() => window.__nightsDebug.closeMachinePanel())

  result.wall = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.createIronWall(0)
    const wall = d.placedWalls[0]
    const entity = { position: { x: wall.x, z: wall.z } }
    d.resolveWorldPropCollisions(entity, 0.34)
    return {
      wall,
      pushed: { x: entity.position.x, z: entity.position.z },
      distance: Math.hypot(entity.position.x - wall.x, entity.position.z - wall.z)
    }
  })

  await page.evaluate(() => {
    const d = window.__nightsDebug
    d.state.ownedTools = { axe: true, pickaxe: true, ironAxe: true, ironSword: true }
    d.updateHud()
    d.updateToolModels()
    d.player.position.x = -2.4
    d.player.position.z = -4.2
    d.state.cameraYaw = 1.75
    d.state.cameraPitch = 0.22
    d.state.cameraDistance = 4.3
  })
  await page.waitForTimeout(450)
  result.layout = await page.evaluate(() => {
    const box = (sel) => {
      const el = document.querySelector(sel)
      const r = el.getBoundingClientRect()
      return { l: Math.round(r.left), t: Math.round(r.top), r: Math.round(r.right), b: Math.round(r.bottom), w: Math.round(r.width), h: Math.round(r.height) }
    }
    const overlaps = (a, b) => a.l < b.r && a.r > b.l && a.t < b.b && a.b > b.t
    const hotbar = box('#hotbar')
    const elements = {
      joystick: box('#joystickZone'),
      drop: box('#dropBtn'),
      jump: box('#jumpBtn'),
      interact: box('#interactBtn'),
      attack: box('#attackBtn')
    }
    return {
      visibleSlots: [...document.querySelectorAll('.hotbar-slot')].filter(e => !e.classList.contains('hidden')).length,
      hotbar,
      elements,
      overlaps: Object.fromEntries(Object.entries(elements).map(([k, v]) => [k, overlaps(hotbar, v)]))
    }
  })
  await page.screenshot({ path: join(outDir, 'hotbar-all-small.png') })

  // Show the machine working from a close three-quarter angle.
  await page.evaluate(() => {
    const d = window.__nightsDebug
    d.state.backpack.wood = 40
    d.state.backpack.iron = 40
    d.state.ownedTools.ironAxe = false
    d.openMachinePanel()
    d.addMachineFuel()
    d.addMachineFuel()
    d.startUpgrade('ironAxe')
