import { createRequire } from 'node:module'
import { readFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, process.platform === 'darwin' ? 'metal.json' : 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const outDir = '/tmp/opencode/browser-test/upgrade7'
mkdirSync(outDir, { recursive: true })
const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 1024, height: 640 }, hasTouch: true, isMobile: false, deviceScaleFactor: 1 })
const errors = []
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message))
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()) })
const result = {}
try {
  await page.goto('http://localhost:3002', { waitUntil: 'load' })
  await page.waitForFunction(() => !!window.__nightsDebug)
  await page.locator('#startBtn').click()
  await page.waitForTimeout(500)

  result.rock = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.state.ownedTools.pickaxe = true
    d.equipTool('pickaxe')
    const rock = d.ironRocks[0]
    d.player.visible = false
    d.player.position.x = rock.x + 1.9
    d.player.position.z = rock.z + 1.9
    d.state.cameraYaw = Math.atan2(rock.x - d.player.position.x, rock.z - d.player.position.z)
    d.state.cameraPitch = 0.18
    d.state.cameraDistance = 4.2
    return { x: rock.x, z: rock.z, hits: rock.hits, visible: rock.group.visible, rocks: d.ironRocks.length }
  })
  await page.waitForTimeout(500)
  await page.screenshot({ path: join(outDir, 'iron-rock.png') })

  result.mine = await page.evaluate(async () => {
    const d = window.__nightsDebug
    const rock = d.ironRocks[0]
    d.mineIronRock(rock)
    const first = { hits: rock.hits, broken: rock.broken }
    d.mineIronRock(rock)
    const drops = d.groundItems.filter(i => i.type === 'iron')
    const playerPos = { x: d.player.position.x, z: d.player.position.z }
    return { first, broken: rock.broken, regrow: rock.regrow, drops: drops.length, closestDrops: drops.map(i => Math.round(Math.hypot(i.x - playerPos.x, i.z - playerPos.z) * 100) / 100) }
  })
  await page.waitForTimeout(800)
  await page.screenshot({ path: join(outDir, 'iron-rock-broken.png') })

  result.pickup = await page.evaluate(() => {
    const d = window.__nightsDebug
    d.player.visible = true
    d.state.backpack = { wood: 0, sapling: 0, berry: 0, iron: 0 }
    d.equipTool('backpack')
    const items = d.groundItems.filter(i => i.type === 'iron' && !i.carried && i.popping <= 0)
    items.forEach(i => d.pickUpItem(i))
    d.updateHud()
    d.setInventoryOpen(true)
    return {
      count: items.length,
      iron: d.state.backpack.iron,
      hud: document.getElementById('ironText').textContent,
