      inventoryText: document.getElementById('inventoryList').innerText,
      ironIcon: !!document.querySelector('.inv-icon.iron'),
      panelVisible: getComputedStyle(document.getElementById('inventoryPanel')).visibility,
      panelOpacity: getComputedStyle(document.getElementById('inventoryPanel')).opacity
    }
  })
  await page.waitForTimeout(250)
  await page.screenshot({ path: join(outDir, 'inventory-iron.png') })

  result.audio = await page.evaluate(async () => {
    const d = window.__nightsDebug
    d.setAudioVolume(0.4)
    await new Promise(r => setTimeout(r, 150))
    const volume = { value: d.audio.volume, gain: d.audio.master.gain.value, label: document.getElementById('volumeValue').textContent }
    d.toggleAudioMute()
    await new Promise(r => setTimeout(r, 150))
    const muted = { muted: d.audio.muted, gain: d.audio.master.gain.value, cls: document.getElementById('audioToggle').classList.contains('muted') }
    d.toggleAudioMute()
    await new Promise(r => setTimeout(r, 150))
    const unmuted = { muted: d.audio.muted, gain: d.audio.master.gain.value }
    return { volume, muted, unmuted, state: d.audio.ctx.state }
  })

  result.regrow = await page.evaluate(() => {
