    rock.regrow = 0.01
    d.updateIronRocks(0.02)
    d.updateIronRocks(0.5)
    return { broken: rock.broken, visible: rock.group.visible, hits: rock.hits, scale: Math.round(rock.group.scale.x * 100) / 100 }
  })

  result.errors = errors
} catch (error) {
  result.failure = String(error && error.stack || error)
  result.errors = errors
  try { await page.screenshot({ path: join(outDir, 'failure.png') }) } catch {}
