    return { set, muted, unmuted, state: d.audio.ctx.state }
  })

  await page.evaluate(() => {
    const d = window.__nightsDebug
    d.state.backpack.wood = 40
    d.state.backpack.iron = 40
    d.machineState.fuel = 100
    d.machineState.working = null
